import csv

# Check t13_city_clusters.csv for any fields with commas in city_name
with open('/benchmark/runs/sweep_v2/workspaces/qwen35_9b_bf16__agent_tools__T13__rep04/outputs/t13_city_clusters.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    print('Header:', header)

    # Check for any rows with commas in city_name that are NOT quoted
    for i, row in enumerate(reader):
        if i > 100:
            break
        city_name = row[1]
        if ',' in city_name:
            if '\"' not in city_name:
                print(f'Row {i}: city_name has comma but is not quoted: {repr(city_name)}')
            else:
                print(f'Row {i}: city_name with comma is properly quoted: {repr(city_name)}')
""}

