# Check if city_name fields with commas are properly quoted in the raw file
with open('outputs/t13_city_clusters.csv', 'r') as f:
    content = f.read()

# Find the row with 'Palmas de Gran Canaria, Las'
lines = content.split('\n')
for i, line in enumerate(lines):
    if 'Palmas de Gran Canaria, Las' in line:
        print(f'Line {i}: {repr(line)}')
        # Check if the line is properly quoted
        if '\"Palmas de Gran Canaria, Las\"' in line:
            print('  -> Properly quoted')
        else:
            print('  -> NOT properly quoted!')
""}
